wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::response_channel;

struct Node;

impl Guest for Node {
    fn run(reply: AgentResponse) -> DeliveryConfirmation {
        // Precondition from the node contract: len(text) <= 100000.
        // Inputs outside the contract never produce an output.
        if reply.text.len() > 100_000 {
            panic!("SendReply: precondition violated: text exceeds 100000 bytes");
        }

        let confirmation = response_channel::send(&reply.text);

        // Postconditions: delivered == true and present(session).
        // A postcondition failure must not produce an output, so trap instead
        // of returning a confirmation that violates the contract.
        if !confirmation.delivered {
            panic!("SendReply: postcondition violated: delivered == false");
        }
        if confirmation.session.is_empty() {
            panic!("SendReply: postcondition violated: session not present");
        }

        confirmation
    }
}

export!(Node);
